/bin/bash -lc "python3 -m py_compile openai_client.py && python3 - <<'PY'
import io
import json
from unittest.mock import patch
from urllib.error import HTTPError, URLError

import openai_client

class FakeOpener:
    def __init__(self, result):
        self.result = result

    def open(self, request, timeout):
        assert request.full_url == 'https://api.openai.com/v1/responses'
        assert request.get_header('Authorization') == 'Bearer test-key'
        assert timeout == 30
        assert json.loads(request.data) == {'model': 'gpt-4.1', 'input': 'private prompt', 'store': False}
        if isinstance(self.result, Exception):
            raise self.result
        return io.BytesIO(self.result)

with patch.object(openai_client, 'build_opener', return_value=FakeOpener(json.dumps({
    'status': 'completed', 'output': [
        {'type': 'reasoning', 'summary': []},
        {'type': 'message', 'content': [{'type': 'output_text', 'text': 'Hello'}]},
    ]
}).encode())):
    assert openai_client.send_prompt('private prompt', api_key='[REDACTED_SECRET]') == 'Hello'

for result in (HTTPError('https://api.openai.com/v1/responses', 401, 'secret', {}, None),
               URLError('secret'), b'not json',
               b'{\"status\":\"incomplete\",\"output\":[]}'):
    with patch.object(openai_client, 'build_opener', return_value=FakeOpener(result)):
        try:
            openai_client.send_prompt('private prompt', api_key='[REDACTED_SECRET]')
        except openai_client.OpenAIError as error:
            assert 'secret' not in str(error)
        else:
            raise AssertionError('expected OpenAIError')
print('Mocked API checks passed')
